def parse(lines):
    for line in lines:
        line = line.strip()
        if line and not line.startswith('#'):
            yield Record.parse(line)                 # stage 1

def enrich(records):
    for rec in records:
        yield rec._replace(total=rec.total * tax)    # stage 2

for rec in enrich(parse(open('orders.txt'))):        # source -> stages -> sink
    sink.write(rec)

